# Generated by build.py from recipe.yml for recipe http-take-timings-with-curl-easy-getinfo. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/fast.txt'), "fast`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/slow.txt'), "slow`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--fault', '"delay;stage=command;path=/slow.txt;ms=1500"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { dotnet run timings.cs -- http://127.0.0.1:8080/fast.txt http://127.0.0.1:8080/slow.txt } finally { Stop-Process $server0 }
